package auth

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"os"
	"path/filepath"
	"testing"

	"github.com/router-for-me/CLIProxyAPI/v8/internal/registry"
	cliproxyexecutor "github.com/router-for-me/CLIProxyAPI/v8/sdk/cliproxy/executor"
)

// The fixture was generated by the previous published fork, before the JSON
// parser migration. Do not regenerate it with the implementation under test.
func TestDurableBindingsSurviveParserMigration(t *testing.T) {
	data, err := os.ReadFile("testdata/durable_pre_moego.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		Source string `json:"source"`
		Cases  []struct {
			Name    string      `json:"name"`
			Payload string      `json:"payload"`
			Headers http.Header `json:"headers"`
			Caller  string      `json:"caller"`
			Owner   string      `json:"owner"`
		} `json:"cases"`
		Bindings json.RawMessage `json:"bindings_file"`
	}
	if err = json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	if fixture.Source != "3cb0bbf9faedb2ce5856b3b16516508113fdec32" || len(fixture.Cases) != 9 {
		t.Fatal("unexpected compatibility fixture")
	}
	path := filepath.Join(t.TempDir(), "bindings.json")
	if err = os.WriteFile(path, fixture.Bindings, 0600); err != nil {
		t.Fatal(err)
	}
	ids := []string{"aa-alternate", "saved-owner-a", "saved-owner-b"}
	for _, id := range ids {
		registry.GetGlobalRegistry().RegisterClient(id, "claude", []*registry.ModelInfo{{ID: "model-one"}, {ID: "model-two"}})
		t.Cleanup(func() { registry.GetGlobalRegistry().UnregisterClient(id) })
	}
	for restart := 0; restart < 2; restart++ {
		selector := NewSessionAffinitySelectorWithConfig(SessionAffinityConfig{File: path, Fallback: &FillFirstSelector{}})
		t.Cleanup(selector.Stop)
		m := NewManager(nil, selector, nil)
		m.RegisterExecutor(schedulerTestExecutor{provider: "claude"})
		for _, id := range ids {
			attributes := map[string]string{}
			if id == "aa-alternate" {
				attributes["priority"] = "100"
			}
			if _, errRegister := m.Register(WithSkipPersist(context.Background()), &Auth{ID: id, Provider: "claude", Status: StatusActive, Attributes: attributes}); errRegister != nil {
				t.Fatal(errRegister)
			}
		}
		for _, c := range fixture.Cases {
			for _, model := range []string{"model-one", "model-two"} {
				opts := cliproxyexecutor.Options{Headers: c.Headers, OriginalRequest: []byte(c.Payload), Metadata: map[string]any{cliproxyexecutor.CallerScopeMetadataKey: c.Caller}}
				owner, errPick := durableTestPick(m, model, opts)
				if errPick != nil {
					t.Fatalf("restart %d, %s, %s: %v", restart, c.Name, model, errPick)
				}
				if owner.ID != c.Owner {
					t.Fatalf("restart %d, %s, %s: owner %q, want %q", restart, c.Name, model, owner.ID, c.Owner)
				}
			}
		}
		selector.Stop()
		persisted, errRead := os.ReadFile(path)
		if errRead != nil {
			t.Fatal(errRead)
		}
		if !bytes.Equal(persisted, fixture.Bindings) {
			t.Fatal("reusing old bindings rewrote the ownership file")
		}
	}
}
